contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Helper to check if a contract supports transferFrom by calling it and expecting no revert
    function supportsTransferFrom(address target) internal returns (bool) {
        // We attempt to call transferFrom on target with dummy arguments
        // Since we don't control the target, we just check that the call doesn't revert
        // We pass address(this) as from and to, and 0 as value
        // If the target doesn't have transferFrom, it will revert
        (bool success,) = target.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", address(this), address(this), 0));
        return success;
    }

    // Fuzz test that checks that after a successful transfer, the target has a balance change
    // consistent with transferFrom semantics (i.e., the call goes through, regardless of revert on target)
    function testFuzz_property(address contract_address, address[] calldata tos, uint[] calldata vs) public {
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);

        // Record the target contract's balance before
        uint256 beforeBalance = contract_address.balance;

        // Call transfer
        (bool success,) = address(c).call(abi.encodeWithSignature("transfer(address,address[],uint256[])", contract_address, tos, vs));

        // The property: the call should always succeed (since the reference C has no reason to revert for valid inputs)
        assertTrue(success, "Transfer call should succeed");
    }
}

