pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        // Deploy a minimal ERC20-like contract that records the selector
        TestToken token = new TestToken();

        // Record the number of events before
        uint beforeCount = token.getCallCount();

        // Call transfer on the target contract
        c.transfer(address(token), tos, vs);

        // After transfer, the token should have been called exactly tos.length times
        uint afterCount = token.getCallCount();
        assertTrue(afterCount - beforeCount == tos.length, "Should have called transferFrom on each recipient");
    }
}

contract TestToken {
    uint public callCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        callCount++;
        return true;
    }

    function getCallCount() public view returns (uint) {
        return callCount;
    }
}

