pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        // Deploy a simple ERC20-like contract that tracks transferFrom calls
        // We'll use a small helper contract to check the difference
        // Since we can't modify C, we'll use a separate contract that records calls
        // But we need to observe the external contract's state after the call
        // For this test, we'll deploy a mock that returns true for transferFrom and records it
        MockERC20 mock = new MockERC20();
        // We need to make the external contract address point to mock
        // But we cannot change the input contract_address; so we assume it's the mock
        vm.assume(contract_address == address(mock));
        // Call transfer
        c.transfer(contract_address, tos, vs);
        // The reference C calls transferFrom, so the mock's transferFromCount should be tos.length
        assertTrue(mock.transferFromCount() == tos.length);
    }
}

contract MockERC20 {
    uint256 public transferFromCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        transferFromCount++;
        return true;
    }
    function transfer(address, uint256) external returns (bool) {
        return true;
    }
}
